		dist[1] = 0; cost = 0;
		priority_queue<pair<int, int> > pq;
		pq.push(make_pair(0, 1));
		for (k = 0; k < N; k++) {
			int w = -pq.top().first;
			int u = pq.top().second;
			pq.pop();
			if (selected[u] == true) {
				k--; continue;
			}
			cost += w; selected[u] = true;
			for (int i = 0; i < E[u].size(); i++) {
				int v = E[u][i].first;
				int w2 = E[u][i].second;
				if (selected[v] == true) continue;
				if (dist[v] > w2) {
