class BFS_Graph:
    def __init__(self, n):
        self.N = n
        self.E = [[] for _ in range(n + 1)]
        self.IN = [0] * (n + 1)

    def is_cycle(self):
        for i in range(1, self.N + 1):
            if self.IN[i] > 0:
                return 1
        return 0

    def insert(self, u, v, w):
        self.E[u].append((v, w))
        self.IN[v] += 1

    def insert_fb(self, u, v, w):
        self.E[u].append((v, w))
        self.E[v].append((u, w))

    def bfs(self, start, end, min_weight):
        visited = [False] * (self.N + 1)
        weight = [INF_LONG] * (self.N + 1)
        Q = deque()
        visited[start] = True
        weight[start] = 0
        Q.append(start)
        while Q:
            u = Q.popleft()
            w = weight[u]
            if u == end:
                break
            for v, c in self.E[u]:
                if c >= min_weight and not visited[v]:
                    Q.append(v)
                    weight[v] = w + c
                    visited[v] = True
        return weight

    def topologicalSort(self):
        order = []
        Q = deque()
        for i in range(1, self.N + 1):
            if not self.IN[i]:
                Q.append(i)
        while Q:
            u = Q.popleft()
            order.append(u)
            for v, _ in self.E[u]:
                if self.IN[v] > 0:
                    self.IN[v] -= 1
                    if not self.IN[v]:
                        Q.append(v)
        return order

    def topologicalSortPQ(self):
        order = []
        pq = []
        for i in range(1, self.N + 1):
            if not self.IN[i]:
                heapq.heappush(pq, -i)
        while pq:
            u = -heapq.heappop(pq)
            order.append(-u)
            for v, _ in self.E[u]:
                if self.IN[v] > 0:
                    self.IN[v] -= 1
                    if not self.IN[v]:
                        heapq.heappush(pq, -v)
        return order

    def f(self):
        for u in range(1, self.N + 1):
            for i, (v, _) in enumerate(self.E[u]):
                if self.IN[v] == 1:
                    IN2 = self.IN[:]
                    self.IN[v] -= 1
                    self.topologicalSort()
                    if not self.is_cycle():
                        return 1
                    self.IN = IN2
        return 0

