        j = len(s2) - 1
        v = []
        while i >= 0 and j >= 0:
            a = int(s1[i]) + int(s2[j])
            v.append(a)
            i -= 1
            j -= 1
        while i >= 0:
            v.append(int(s1[i]))
            i -= 1
        while j >= 0:
            v.append(int(s2[j]))
            j -= 1
        carry = 0
        for i in range(len(v)):
            carry += v[i]
            if carry >= 10:
                v[i] = carry - 10
                carry = 1
            else:
