class PrimeNumber:
    def __init__(self, n=None):
        if n:
            self.N = n
            self.NP = [0] * (n + 4)
            self.P = []
            for i in range(2, int(n ** 0.5) + 1):
                if self.NP[i]:
                    continue
                for j in range(i * i, n + 1, i):
                    self.NP[i] = 1
            for i in range(2, n + 1):
                if not self.NP[i]:
                    self.P.append(i)

    def _powmod(self, a, b):
        if b == 0:
            return 1
        if b & 1:
            return (a * self._powmod(a, b - 1)) % MOD
        return self._powmod((a * a) % MOD, b // 2)

    def gcd(self, x, y):
        while x:
            z = y % x
            y = x
            x = z
        return y

    def powermod(self, p, q):
        g = self.gcd(p, q)
        p //= g
        q //= g
        return (p * self._powmod(q, MOD - 2)) % MOD

    def factorization(self, x):
        ret = []
        if x == 1:
            ret.append(1)
            return ret
        ret.append(1)
        ret.append(x)
        i = 2
        while i * i < x:
            if x % i == 0:
                ret.append(i)
                ret.append(x // i)
            i += 1
        if i * i == x:
            ret.append(i)
        return ret

    def factorization2(self, x):
        if x == 1:
            return 1
        ret = 2
        i = 2
        while i * i < x:
            if x % i == 0:
                ret += 2
            i += 1
        if i * i == x:
            ret += 1
        return ret

