        for i in range(n + 1):
            self.C[i][i] = 1
            self.C[i][0] = 1
        for i in range(1, n + 1):
            for j in range(1, i):
                self.C[i][j] = (self.C[i - 1][j - 1] + self.C[i - 1][j]) % MOD
        self.F = [0] * (n + 1)
        self.F[0] = self.F[1] = 1
        for i in range(1, n + 1):
            self.F[i] = (self.F[i - 1] * i) % MOD

