        if n == r or r == 0:
            return 1
        if n <= 1000:
            return self.getC(n, r)
        if r > n // 2:
            r = n - r
        ret = 1
        for i in range(n, n - r, -1):
            ret *= i
        for i in range(2, r + 1):
            ret //= i
        return ret

