class PSum:
    def makeSum(self, a, n=None):
        if n is None:
            ret = a[:]
            for i in range(1, len(a)):
                ret[i] = ret[i - 1] + a[i]
            return ret
        else:
            m = len(a[0])
            ret = [[0] * m for _ in range(n)]
            for i in range(n):
                ret[i][0] = a[i][0]
                for j in range(1, m):
                    ret[i][j] = ret[i][j - 1] + a[i][j]
            return ret

    def getSum(self, psum, a, b, c=None, d=None):
        if c is None:
            if a == 0:
                return psum[b]
            return psum[b] - psum[a - 1]
        else:
            r1, c1, r2, c2 = a, b, c, d
            ret = psum[r2][c2]
            if r1 > 0:
                ret -= psum[r1 - 1][c2]
            if c1 > 0:
                ret -= psum[r2][c1 - 1]
            if r1 > 0 and c1 > 0:
                ret += psum[r1 - 1][c1 - 1]
            return ret

class DisjointSet:
    def __init__(self, n):
        self.N = n
        self.P = list(range(n + 1))
        self.R = [0] * (n + 1)
        self.A = [1] * (n + 1)

    def getA(self, x):
        return self.A[x]

    def find_set(self, x):
        if self.P[x] != x:
            self.P[x] = self.find_set(self.P[x])
        return self.P[x]

    def union_set(self, x, y):
        px = self.find_set(x)
        py = self.find_set(y)
        if px == py:
            return px
        if self.R[px] > self.R[py]:
            self.P[py] = px
            self.A[px] += self.A[py]
            return px
        else:
            self.P[px] = py
            self.A[py] += self.A[px]
            if self.R[px] == self.R[py]:
                self.R[py] += 1
            return py

class LIS:
    def __init__(self, n):
