    def execute(self, A):
        v = [A[0]]
        for x in A[1:]:
            if x > v[-1]:
                v.append(x)
            else:
                lo, hi = 0, len(v) - 1
                while lo < hi:
                    mid = (lo + hi) // 2
                    if v[mid] >= x:
                        hi = mid
                    else:
                        lo = mid + 1
                v[lo] = x
        return len(v)

