        v = [A[0]]
        v1 = [0]
        p = [-1] * len(A)
        for i in range(1, len(A)):
            if v[-1] < A[i]:
                p[i] = v1[-1]
                v.append(A[i])
                v1.append(i)
            else:
                import bisect
                idx = bisect.bisect_left(v, A[i])
                v[idx] = A[i]
                if idx != 0:
                    p[i] = v1[idx - 1]
                v1[idx] = i
        len_ = len(v1)
        ret = [0] * len_
        i = v1[-1]
        j = len_ - 1
        while i != -1:
            ret[j] = A[i]
            i = p[i]
            j -= 1
        return ret

    def execute3(self, A):
        n = len(A)
        v = [0] * n
        for i in range(n):
            for j in range(i):
                if A[j] < A[i] and v[i] < v[j]:
                    v[i] = v[j]
            v[i] += 1
        return max(v)

