        self.A = [0] * (n + 4)

    def setA(self, x, y):
        self.A[x] = y

    def init(self):
        self._init(1, self.N, 1)

    def _init(self, left, right, node):
        if left == right:
            self.ST[node] = self.A[left]
            return self.ST[node]
        mid = (left + right) // 2
        lv = self._init(left, mid, node * 2)
        rv = self._init(mid + 1, right, node * 2 + 1)
        self.ST[node] = lv + rv
        return self.ST[node]

    def query(self, left, right):
        return self._query(left, right, 1, 1, self.N)

