        if right < nodeLeft or nodeRight < left:
            return 0
        if left <= nodeLeft and nodeRight <= right:
            return self.ST[node]
        mid = (nodeLeft + nodeRight) // 2
        lv = self._query(left, right, node * 2, nodeLeft, mid)
        rv = self._query(left, right, node * 2 + 1, mid + 1, nodeRight)
        return lv + rv

    def update(self, index, newValue):
        return self._update(index, newValue, 1, 1, self.N)

    def _update(self, index, newValue, node, nodeLeft, nodeRight):
        if index < nodeLeft or nodeRight < index:
            return self.ST[node]
        if nodeLeft == nodeRight:
            self.ST[node] = newValue
            return self.ST[node]
        mid = (nodeLeft + nodeRight) // 2
        lv = self._update(index, newValue, node * 2, nodeLeft, mid)
        rv = self._update(index, newValue, node * 2 + 1, mid + 1, nodeRight)
        self.ST[node] = lv + rv
        return self.ST[node]

